local function btn(nm,id,fn,bc)
    local b = Instance.new("TextButton") b.Name,b.Parent,b.BackgroundColor3,b.BorderColor3,b.BorderSizePixel,b.Size,b.Font,b.Text,b.TextColor3,b.TextSize = id,B,bc or Color3.fromRGB(30,5,5),Color3.fromRGB(255,0,0),1,UDim2.new(1,0,0,45),Enum.Font.SourceSansBold,nm,Color3.fromRGB(255,255,255),18
    b.MouseButton1Click:Connect(fn) return b
end
local function txt(ph,pd,fn)
    local c,l,x = Instance.new("Frame"),Instance.new("TextLabel"),Instance.new("TextBox") c.Parent,c.Size,c.BackgroundTransparency = B,UDim2.new(1,0,0,45),1
    l.Parent,l.Size,l.BackgroundTransparency,l.Font,l.Text,l.TextColor3,l.TextSize = c,UDim2.new(0.5,0,1,0),1,Enum.Font.SourceSansBold,ph..":",Color3.fromRGB(255,255,255),18
    x.Parent,x.Position,x.Size,x.BackgroundColor3,x.BorderColor3,x.BorderSizePixel,x.Font,x.Text,x.TextColor3,x.TextSize,x.PlaceholderText = c,UDim2.new(0.5,0,0,0),UDim2.new(0.5,0,1,0),Color3.fromRGB(20,5,5),Color3.fromRGB(255,0,0),1,Enum.Font.SourceSansBold,tostring(pd),Color3.fromRGB(255,0,0),18,ph
    x.FocusLost:Connect(function() local n=tonumber(x.Text) if n then fn(n) end end)
end
local function lbl(txt) local l = Instance.new("TextLabel") l.Parent,l.Size,l.BackgroundTransparency,l.Font,l.Text,l.TextColor3,l.TextSize,l.TextYAlignment = B,UDim2.new(1,0,0,30),1,Enum.Font.SourceSansBold,txt,Color3.fromRGB(255,0,0),16,Enum.TextYAlignment.Bottom return l end
local function dF() f = false if B:FindFirstChild("Fly") then B.Fly.Text = "Fly: OFF" end if fCn then fCn:Disconnect() end local r,h = P.Character and P.Character:FindFirstChild("HumanoidRootPart"),P.Character and P.Character:FindFirstChildOfClass("Humanoid") if r then if r:FindFirstChild("IYFlyBV") then r.IYFlyBV:Destroy() end if r:FindFirstChild("IYFlyBG") then r.IYFlyBG:Destroy() end end if h then h.PlatformStand = false end end
local function dN() n = false if B:FindFirstChild("Noclip") then B.Noclip.Text = "Noclip: OFF" end if nCn then nCn:Disconnect() end end
local function remPart(nt) if P.Character then for _,v in pairs(nt) do local p=P.Character:FindFirstChild(v) if p then p:Destroy() end end end end
