btn("Noclip: OFF","Noclip",function() n = not n B.Noclip.Text = n and "Noclip: ON" or "Noclip: OFF" if n then dF() nCn = R.Stepped:Connect(function() if not n then nCn:Disconnect() return end if P.Character then for _,v in pairs(P.Character:GetDescendants()) do if v:IsA("BasePart") then v.CanCollide = false end end end end) else if nCn then nCn:Disconnect() end end end)
btn("Jerk: OFF","Jerk",function() j = not j B.Jerk.Text = j and "Jerk: ON" or "Jerk: OFF" task.spawn(function() while j do local t = P.Character and (P.Character:FindFirstChild("Torso") or P.Character:FindFirstChild("LowerTorso")) local r = t and (t:FindFirstChild("RootJoint") or P.Character.HumanoidRootPart:FindFirstChild("RootJoint")) if r then r.C0 = r.C0 * CFrame.new(0,0,-0.5) task.wait(0.1) r.C0 = r.C0 * CFrame.new(0,0,0.5) task.wait(0.1) else task.wait(0.5) end end local t = P.Character and (P.Character:FindFirstChild("Torso") or P.Character:FindFirstChild("LowerTorso")) local r = t and (t:FindFirstChild("RootJoint") or P.Character.HumanoidRootPart:FindFirstChild("RootJoint")) if r then r.C0 = CFrame.new(0,0,0) * CFrame.Angles(-math.pi/2,0,math.pi) end end) end)
btn("Fly: OFF","Fly",function() f = not f B.Fly.Text = f and "Fly: ON" or "Fly: OFF" local r,h = P.Character and P.Character:FindFirstChild("HumanoidRootPart"),P.Character and P.Character:FindFirstChildOfClass("Humanoid") if not r or not h then return end if f then dN() h.PlatformStand = true local bv,bg = Instance.new("BodyVelocity"),Instance.new("BodyGyro") bv.Name,bv.MaxForce,bv.Velocity,bv.Parent = "IYFlyBV",Vector3.new(1,1,1)*math.huge,Vector3.new(0,0,0),r bg.Name,bg.MaxTorque,bg.CFrame,bg.Parent = "IYFlyBG",Vector3.new(1,1,1)*math.huge,r.CFrame,r fCn = R.Heartbeat:Connect(function() if not f or not r or not r.Parent then dF() return end local c,m = workspace.CurrentCamera,h.MoveDirection if m.Magnitude > 0 then local fD = (c.CFrame.LookVector * m:Dot(c.CFrame.LookVector)) + (c.CFrame.RightVector * m:Dot(c.CFrame.RightVector)) bv.Velocity = fD.Unit * fSp else bv.Velocity = Vector3.new(0,0,0) end bg.CFrame = c.CFrame end) else dF() end end)
btn("Mudar FOV","FOV",function() s = not s workspace.CurrentCamera.FieldOfView = s and 120 or 70 end)
btn("Spin","Spin",function() s = not s local r = P.Character and P.Character:FindFirstChild("HumanoidRootPart") if r then if s then local a = Instance.new("BodyAngularVelocity",r) a.Name,a.MaxTorque,a.AngularVelocity = "SpinningVelocity",Vector3.new(0,math.huge,0),Vector3.new(0,45,0) else if r:FindFirstChild("SpinningVelocity") then r.SpinningVelocity:Destroy() end end end end)
btn("Fling","Fling",function() fl = not fl local r = P.Character and P.Character:FindFirstChild("HumanoidRootPart") if r then if fl then local b = Instance.new("BodyVelocity",r) b.Name,b.MaxForce,b.Velocity = "FlingVelocity",Vector3.new(1,0,1)*math.huge,Vector3.new(20000,0,20000) else if r:FindFirstChild("FlingVelocity") then r.FlingVelocity:Destroy() end end end end)
btn("Light: OFF","Light",function() li = not li B.Light.Text = li and "Light: ON" or "Light: OFF" local r = P.Character and P.Character:FindFirstChild("HumanoidRootPart") if r then if li then local l = Instance.new("PointLight",r) l.Name,l.Color,l.Range,l.Brightness = "WolfLight",Color3.fromRGB(255,0,0),30,5 else if r:FindFirstChild("WolfLight") then r.WolfLight:Destroy() end end end end)
