btn("Freecam: OFF","Freecam",function() fc = not fc B.Freecam.Text = fc and "Freecam: ON" or "Freecam: OFF" local c = workspace.CurrentCamera local h = P.Character and P.Character:FindFirstChildOfClass("Humanoid") if fc then if h then h.WalkSpeed = 0 end c.CameraType = Enum.CameraType.Custom local fPart = Instance.new("Part", workspace) fPart.Name, fPart.Size, fPart.Transparency, fPart.Anchored, fPart.CanCollide = "WolfFC", Vector3.new(1,1,1), 1, true, false fPart.CFrame = c.CFrame c.CameraSubject = fPart fcCn = R.RenderStepped:Connect(function() if not fc or not fPart then fcCn:Disconnect() return end local m = h and h.MoveDirection or Vector3.new() if m.Magnitude > 0 then local fAmount = m:Dot(c.CFrame.LookVector) local rAmount = m:Dot(c.CFrame.RightVector) local moveDir = (c.CFrame.LookVector * fAmount) + (c.CFrame.RightVector * rAmount) fPart.CFrame = fPart.CFrame + (moveDir.Unit * 1.5) end end) else if fcCn then fcCn:Disconnect() end c.CameraType = Enum.CameraType.Custom if h then h.WalkSpeed = tSp c.CameraSubject = h end if workspace:FindFirstChild("WolfFC") then workspace.WolfFC:Destroy() end end end)
